{"content": "{
  "main_characters": [
    {
      "name": "路远征",
      "role": "protagonist",
      "identity": "倒爷（个体户），骑嘉陵CJ70摩托车穿州过省倒卖南方货物到北方",
      "traits": ["孤注一掷的赌徒气", "嘴笨但行动浪漫", "外表粗粝内心细腻", "死要面子"],
      "overt_motivation": "把这批南方货安全运到北方卖掉，赚够本钱翻身",
      "covert_motivation": "用这趟生意证明自己配得上秦萤——一个倒爷也能给她一个家",
      "secret_fear": "害怕秦萤发现他其实已经走投无路，这是他最后的赌注，赔了就真的什么都没有了",
      "misperception_of_other": "以为秦萤只是为了挣那两百块钱押货费才跟他上路，不知道她早就对他有了依赖",
      "hidden_connection": "三个月前在秦萤下岗那天见过她一面——她蹲在厂门口哭，他骑摩托经过，停下来递了根冰棍"
    },
    {
      "name": "秦萤",
      "role": "deuteragonist",
      "identity": "国营棉纺厂下岗女工，28岁，未婚",
      "traits": ["倔强隐忍", "心思细密但不说破", "骨子里有冒险精神", "嘴硬心软"],
      "overt_motivation": "挣两百块押货费，解决眼前的生存问题",
      "covert_motivation": "在漂泊中寻找一种确定感——有人愿意带着她走，不管走向哪里",
      "secret_fear": "害怕被丢下——父亲出走、工厂抛弃，她怕路远征也只是另一个会消失的人",
      "misperception_of_other": "以为路远征只把她当押货的工具人，买枕巾只是进货行为，不知道那是给她的聘礼",
      "hidden_connection": "记得三个月前那根冰棍，但一直没认出路远征——直到第四天他在暴雨中停车给她买红丝巾时的侧脸"
    }
  ],
  "supporting_characters": [
    {
      "name": "齐老板",
      "function": "反转点",
      "identity": "北方县城百货商店老板，路远征此行的收货方",
      "description": "精明的北方商人，本来答应按原价收货，但因市场行情变动压价到成本以下。他的拒绝是整个故事'赔了'的直接原因，也是迫使男女主角做出最终抉择的催化剂。与路远征有过几次生意往来，算半个熟人，但生意场上翻脸无情。"
    },
    {
      "name": "老孙头",
      "function": "助力",
      "identity": "路边摩托车修理铺老板，湖北某县",
      "description": "路途中遇到的修车师傅，替他们修好了爆胎的摩托。修车时看出路远征对秦萤的心思，调侃了一句'你这边斗里装的是货还是嫁妆'，无意中点破了路远征的秘密，让秦萤第一次产生疑惑。老孙头自己也是骑摩托走南闯北的老江湖，修完车只收了一条烟的钱。"
    }
  ],
  "relationship_dynamics": "路远征与秦萤的关系经历四个阶段，对应'漂泊的确定'这一单频振动：\n\n【第一阶段·雇佣】（第1天）路远征以'押货两百块'为由带秦萤上路，两人是纯粹的雇主与雇员关系。秦萤坐在后座保持距离，路远征专注赶路不多话。表面冷淡，但路远征每次停车都会先把边斗里的枕巾往外挪，给她腾出靠背的空间。\n\n【第二阶段·共谋】（第2-4天）摩托爆胎、遇到暴雨、路上被交警拦，共同应对困难让雇佣关系松动。秦萤开始主动帮忙看地图、算油钱、跟加油站小贩砍价。路远征暗中在每个县城供销社买一对鸳鸯枕巾，秦萤注意到边斗里的枕巾越来越多但没有追问。老孙头'嫁妆'的玩笑让秦萤第一次怀疑这些枕巾的意义。关系转折点：暴雨中路远征停车给她买红丝巾，秦萤认出了三个月前递冰棍的侧脸。\n\n【第三阶段·定情】（第5-6天）秦萤开始偷偷在地图上经过的城市画心。两人默契地不说破但彼此试探：她帮他把枕巾叠整齐，他把摩托开得更慢（怕路太快就到了）。第六夜在桥洞避雨过夜，路远征把所有枕巾铺开当床，说'现在我们有一万张婚床'——这是他第一次半真半假地袒露心意，秦萤没有回应但也没有走开。\n\n【第四阶段·新生】（第7天）到达目的地，齐老板压价，生意赔了。路远征说出赌约——赚了娶你，赔了摩托归你我归摩托。秦萤第一次主动握住他的手，把摩托卖了，买了两张去深圳的车票。关系从'他带她走'逆转为'她带他走'，完成了漂泊中的确定。"
}
